local CarpetLoom = {}
local PRODUCTS = {
    rush_mat = { name = "Trotasta preproga", rushCost = 2, time = 1, cost = 10, warmth = 3, description = "Preprosta trotasta preproga za kmete." },
    wool_rug = { name = "Volnena preproga", woolCost = 2, time = 3, cost = 50, warmth = 6, prestige = 1, description = "Volnena preproga z geometrijskim vzorcem." },
    dyed_carpets = { name = "Barvna preproga", woolCost = 2, dyeCost = 1, time = 5, cost = 130, warmth = 8, prestige = 4, happiness = 1, description = "Barvno tkana preproga." },
    knotted_rug = { name = "Vozlana preproga", woolCost = 3, silkCost = 1, time = 7, cost = 320, warmth = 10, prestige = 9, happiness = 2, description = "Vozlana preproga s slovenskim vzorcem." },
    silk_persian = { name = "Svilena perzijska", silkCost = 3, dyeCost = 2, time = 10, cost = 720, warmth = 12, prestige = 18, happiness = 4, description = "Svilena perzijska preproga za plemiče." },
    royal_hunting_carpet = { name = "Kraljevska lovna preproga", silkCost = 4, goldCost = 1, silverCost = 1, jewelCost = 1, dyeCost = 2, time = 14, cost = 1800, warmth = 16, prestige = 45, happiness = 10, description = "Veliki kraljevski lovni prizor z zlatimi in draguljnimi detajli." },
}
local BUILDINGS = {
    workshop = { name = "Tkalna delavnica", cost = { gold = 250, wood = 130 }, upkeep = 6, qualityBonus = 5 },
    loom_room = { name = "Stenska tkalnica", cost = { gold = 800, wood = 250, stone = 200, wool = 10 }, upkeep = 20, qualityBonus = 18 },
    dyeing_room = { name = "Barvilnica", cost = { gold = 1700, wood = 300, stone = 350, silver = 25, dye = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_carpet_atelier = { name = "Kraljevski atelje preprog", cost = { gold = 6500, wood = 600, stone = 700, gold = 50, silk = 20 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
CarpetLoom.rushStock = 16; CarpetLoom.woolStock = 14; CarpetLoom.silkStock = 8; CarpetLoom.dyeStock = 8; CarpetLoom.goldStock = 6; CarpetLoom.silverStock = 6; CarpetLoom.jewelStock = 4
CarpetLoom.productStock = {}; CarpetLoom.buildings = {}; CarpetLoom.maker = nil; CarpetLoom.activeMaking = {}; CarpetLoom.totalProducts = 0; CarpetLoom.dayTimer = 0
function CarpetLoom.init() CarpetLoom.rushStock=16; CarpetLoom.woolStock=14; CarpetLoom.silkStock=8; CarpetLoom.dyeStock=8; CarpetLoom.goldStock=6; CarpetLoom.silverStock=6; CarpetLoom.jewelStock=4; CarpetLoom.productStock={}; CarpetLoom.buildings={}; CarpetLoom.maker=nil; CarpetLoom.activeMaking={}; CarpetLoom.totalProducts=0; CarpetLoom.dayTimer=0; print("[CarpetLoom] Royal Carpet Loom System initialized (6 products, 4 buildings)") end
function CarpetLoom.hireMaker(n,s) s=s or math.random(50,90); local c=470+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CarpetLoom.maker={name=n or ("Tkalcar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tkalcar najet: %s (spretnost: %d)",CarpetLoom.maker.name,s),"success") end; return true end
function CarpetLoom.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CarpetLoom.build(id) local ok,e=CarpetLoom.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CarpetLoom.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CarpetLoom.getQualityBonus() local b=0; for _,bd in ipairs(CarpetLoom.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CarpetLoom.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.rushCost and CarpetLoom.rushStock<(d.rushCost or 0) then return false,"Premalo rogoza" end; if d.woolCost and CarpetLoom.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.silkCost and CarpetLoom.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.dyeCost and CarpetLoom.dyeStock<(d.dyeCost or 0) then return false,"Premalo barvila" end; if d.goldCost and CarpetLoom.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.silverCost and CarpetLoom.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.jewelCost and CarpetLoom.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #CarpetLoom.buildings==0 then return false,"Potrebna delavnica" end; if not CarpetLoom.maker then return false,"Potreben tkalcar" end; return true end
function CarpetLoom.make(pt,qty) qty=qty or 1; local ok,e=CarpetLoom.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.rushCost then CarpetLoom.rushStock=CarpetLoom.rushStock-d.rushCost*qty end; if d.woolCost then CarpetLoom.woolStock=CarpetLoom.woolStock-d.woolCost*qty end; if d.silkCost then CarpetLoom.silkStock=CarpetLoom.silkStock-d.silkCost*qty end; if d.dyeCost then CarpetLoom.dyeStock=CarpetLoom.dyeStock-d.dyeCost*qty end; if d.goldCost then CarpetLoom.goldStock=CarpetLoom.goldStock-d.goldCost*qty end; if d.silverCost then CarpetLoom.silverStock=CarpetLoom.silverStock-d.silverCost*qty end; if d.jewelCost then CarpetLoom.jewelStock=CarpetLoom.jewelStock-d.jewelCost*qty end; local t=d.time; if CarpetLoom.maker then t=math.max(1,t-math.floor(CarpetLoom.maker.skill/12)) end; table.insert(CarpetLoom.activeMaking,{id="carpet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,warmth=d.warmth or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CarpetLoom.completeMaking(m) local q=1.0+(CarpetLoom.getQualityBonus()/100); if CarpetLoom.maker then q=q+(CarpetLoom.maker.skill/180) end; q=math.min(2.0,q); CarpetLoom.productStock[m.productType]=(CarpetLoom.productStock[m.productType] or 0)+m.quantity; CarpetLoom.totalProducts=CarpetLoom.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CarpetLoom.maker then CarpetLoom.maker.itemsMade=CarpetLoom.maker.itemsMade+m.quantity; if math.random()<0.20 then CarpetLoom.maker.skill=math.min(100,CarpetLoom.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Preproga izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"carpet.completed",{productName=m.productName,prestige=m.prestige}) end end
function CarpetLoom.update(dt) if not _G.state then return end; CarpetLoom.dayTimer=CarpetLoom.dayTimer+dt; if CarpetLoom.dayTimer>=30 then CarpetLoom.dayTimer=0; for i=#CarpetLoom.activeMaking,1,-1 do local m=CarpetLoom.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CarpetLoom.completeMaking(m); table.remove(CarpetLoom.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CarpetLoom.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CarpetLoom.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CarpetLoom.getStats() return {rushStock=CarpetLoom.rushStock,woolStock=CarpetLoom.woolStock,silkStock=CarpetLoom.silkStock,dyeStock=CarpetLoom.dyeStock,goldStock=CarpetLoom.goldStock,silverStock=CarpetLoom.silverStock,jewelStock=CarpetLoom.jewelStock,productStock=CarpetLoom.productStock,numBuildings=#CarpetLoom.buildings,hasMaker=CarpetLoom.maker~=nil,makerName=CarpetLoom.maker and CarpetLoom.maker.name or "—",makerSkill=CarpetLoom.maker and CarpetLoom.maker.skill or 0,activeMaking=#CarpetLoom.activeMaking,totalProducts=CarpetLoom.totalProducts} end
return CarpetLoom
